    skid_buffer #(.WIDTH(8)) skid (
        .clk(clk),
        .rst_n(rst_n),
        .in_valid(in_valid),
        .in_data(in_data),
        .out_valid(skid_out_valid),
        .out_data(skid_out_data),
        .out_ready(acc_sample_ready),
        .in_ready(skid_in_ready)
    );

    accumulator_core #(.WIDTH(8)) acc (
        .clk(clk),
