`timescale 1ns/1ns
module accumulator_core #(
    parameter DATA_WIDTH = 8,
    parameter SUM_WIDTH = 16
) (
    input wire clk,
    input wire rst_n,
    input wire sample_valid,
    input wire [2*DATA_WIDTH-1:0] sample,
    output wire sample_ready,
    output wire sum_valid,
    output wire [SUM_WIDTH-1:0] sum,
    input wire sum_ready
);

reg [SUM_WIDTH-1:0] acc;
reg valid;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        acc <= 0;
        valid <= 1'b0;
    end else begin
        if (sum_ready && valid) begin
            valid <= 1'b0;
        end
        if (sample_valid && !valid) begin
            acc <= acc + sample;
            valid <= 1'b1;
        end
    end
end

assign sample_ready = !valid;
assign sum_valid = valid;
assign sum = acc;

endmodule

`timescale 1ns/1ns
module skid_buffer #(
    parameter DATA_WIDTH = 8
) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    input wire [DATA_WIDTH-1:0] in_data,
    output wire in_ready,
    output wire out_valid,
    output wire [DATA_WIDTH-1:0] out_data,
    input wire out_ready
);

reg buffer_valid;
reg [DATA_WIDTH-1:0] buffer_data;
reg bypass;

wire fifo_full;
assign fifo_full = buffer_valid;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        buffer_valid <= 1'b0;
        bypass <= 1'b0;
    end else begin
        if (out_ready && buffer_valid) begin
            buffer_valid <= 1'b0;
        end
        if (in_valid && (in_ready || bypass)) begin
            if (out_ready && !buffer_valid) begin
                // direct bypass
                bypass <= 1'b1;
            end else begin
                buffer_data <= in_data;
                buffer_valid <= 1'b1;
                bypass <= 1'b0;
            end
        end else if (in_valid && in_ready && out_ready && buffer_valid) begin
            // when buffer is full but both ready, we can bypass
            bypass <= 1'b1;
        end else if (bypass && out_ready) begin
            bypass <= 1'b0;
        end
    end
end

assign in_ready = !fifo_full || (out_ready && !bypass);
assign out_valid = bypass || buffer_valid;
assign out_data = bypass ? in_data : buffer_data;

endmodule

`timescale 1ns/1ns
module stream_join #(
    parameter DATA_WIDTH = 8
) (
    input wire clk,
    input wire rst_n,
    input wire in0_valid,
    input wire [DATA_WIDTH-1:0] in0_data,
    output wire in0_ready,
    input wire in1_valid,
    input wire [DATA_WIDTH-1:0] in1_data,
    output wire in1_ready,
    output wire out_valid,
    output wire [2*DATA_WIDTH-1:0] out_data,
    input wire out_ready
);

reg join_valid;
reg [2*DATA_WIDTH-1:0] join_data;

assign in0_ready = !join_valid || out_ready;
assign in1_ready = !join_valid || out_ready;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        join_valid <= 1'b0;
    end else begin
        if (out_ready && join_valid) begin
            join_valid <= 1'b0;
        end
        if (in0_valid && in1_valid && !join_valid) begin
            join_valid <= 1'b1;
            join_data <= {in0_data, in1_data};
        end
    end
end

assign out_valid = join_valid;
assign out_data = join_data;

endmodule

`timescale 1ns/1ns
module stream_stage #(
    parameter DATA_WIDTH = 16
) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    input wire [DATA_WIDTH-1:0] in_data,
    output wire in_ready,
    output wire out_valid,
    output wire [DATA_WIDTH-1:0] out_data,
    input wire out_ready
);

reg pipe_valid;
reg [DATA_WIDTH-1:0] pipe_data;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        pipe_valid <= 1'b0;
    end else begin
        if (out_ready && pipe_valid) begin
            pipe_valid <= 1'b0;
        end
        if (in_valid && (!pipe_valid || out_ready)) begin
            pipe_data <= in_data;
            pipe_valid <= 1'b1;
        end
    end
end

assign in_ready = !pipe_valid || out_ready;
assign out_valid = pipe_valid;
assign out_data = pipe_data;

endmodule

