module accumulator_core #(
    parameter DATA_WIDTH = 8,
    parameter ACCUM_WIDTH = 16
) (
    input  wire                clk,
    input  wire                rst_n,
    input  wire                in_valid,
    input  wire [DATA_WIDTH-1:0] in_data,
    output wire                in_ready,
    output wire                out_valid,
    output wire [ACCUM_WIDTH-1:0] out_data,
    input  wire                out_ready
);

    localparam IDLE = 2'b00;
    localparam ACCUMULATE = 2'b01;
    localparam OUTPUT = 2'b10;

    reg [1:0] state, next_state;
    reg [ACCUM_WIDTH-1:0] accum_reg;
    reg [ACCUM_WIDTH-1:0] out_reg;
    reg out_valid_reg;

    assign in_ready = (state == IDLE);
    assign out_valid = out_valid_reg;
    assign out_data = out_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            accum_reg <= 0;
            out_valid_reg <= 1'b0;
        end else begin
            state <= next_state;
            if (state == ACCUMULATE) begin
                accum_reg <= accum_reg + in_data;
                out_reg <= accum_reg + in_data; // precompute for next cycle
            end
            if (next_state == OUTPUT) begin
                out_valid_reg <= 1'b1;
            end else if (out_valid_reg && out_ready) begin
                out_valid_reg <= 1'b0;
            end
        end
    end

    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (in_valid) begin
                    next_state = ACCUMULATE;
                end
            end
            ACCUMULATE: begin
                next_state = OUTPUT;
            end
            OUTPUT: begin
                if (out_ready) begin
                    next_state = IDLE;
                end
            end
        endcase
    end

endmodule

module skid_buffer #(
    parameter DATA_WIDTH = 8
) (
    input  wire                clk,
    input  wire                rst_n,
    input  wire                in_valid,
    input  wire [DATA_WIDTH-1:0] in_data,
    output wire                in_ready,
    output wire                out_valid,
    output wire [DATA_WIDTH-1:0] out_data,
    input  wire                out_ready
);

    reg [DATA_WIDTH-1:0] buf0, buf1;
    reg [1:0] fill_count; // 0 empty, 1 one in buf0, 2 both
    reg [DATA_WIDTH-1:0] out_reg;
    reg out_valid_reg;

    wire pop = out_valid_reg && out_ready;
    wire push = in_valid && in_ready;

    assign in_ready = (fill_count < 2) ? 1'b1 : 1'b0;
    assign out_valid = out_valid_reg;
    assign out_data = out_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            fill_count <= 2'b0;
            out_valid_reg <= 1'b0;
        end else begin
            case (fill_count)
                2'b00: begin
                    if (push) begin
                        // store in buf0
                        buf0 <= in_data;
                        fill_count <= 2'b01;
                        out_valid_reg <= 1'b1;
                        out_reg <= in_data;
                    end
                end
                2'b01: begin
                    if (pop) begin
                        if (push) begin
                            // push into buf0, no pop
                            buf0 <= in_data;
                            out_reg <= buf0;
                        end else begin
                            out_valid_reg <= 1'b0;
                            fill_count <= 2'b00;
                        end
                    end else begin
                        if (push) begin
                            buf1 <= in_data;
                            fill_count <= 2'b10;
                        end
                    end
                end
                2'b10: begin
                    if (pop) begin
                        out_reg <= buf1;
                        if (push) begin
                            buf0 <= in_data;
                            fill_count <= 2'b01;
                        end else begin
                            fill_count <= 2'b01;
                        end
                    end else begin
                        if (push) begin
                            // no space, should not happen due to in_ready
                        end
                    end
                end
            endcase
        end
    end

endmodule

module stream_join #(
    parameter DATA_WIDTH = 8
) (
    input  wire                clk,
    input  wire                rst_n,
    input  wire                in0_valid,
    input  wire [DATA_WIDTH-1:0] in0_data,
    output wire                in0_ready,
    input  wire                in1_valid,
    input  wire [DATA_WIDTH-1:0] in1_data,
    output wire                in1_ready,
    output wire                out_valid,
    output wire [DATA_WIDTH-1:0] out_data,
    input  wire                out_ready
);

    localparam IDLE = 2'b00;
    localparam WAIT_BOTH = 2'b01;
    localparam PASS = 2'b10;

    reg [1:0] state, next_state;
    reg in0_valid_reg, in1_valid_reg;
    reg [DATA_WIDTH-1:0] in0_data_reg, in1_data_reg;
    reg out_valid_reg;
    reg [DATA_WIDTH-1:0] out_data_reg;

    assign in0_ready = (state == IDLE || state == WAIT_BOTH);
    assign in1_ready = (state == IDLE || state == WAIT_BOTH);
    assign out_valid = out_valid_reg;
    assign out_data = out_data_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            in0_valid_reg <= 1'b0;
            in1_valid_reg <= 1'b0;
            out_valid_reg <= 1'b0;
        end else begin
            state <= next_state;
            // capture data on handshake
            if (in0_valid && in0_ready) begin
                in0_valid_reg <= 1'b1;
                in0_data_reg <= in0_data;
            end
            if (in1_valid && in1_ready) begin
                in1_valid_reg <= 1'b1;
                in1_data_reg <= in1_data;
            end
            // output generation
            if (next_state == PASS) begin
                out_valid_reg <= 1'b1;
                // Join operation: sum of two inputs (truncated to DATA_WIDTH)
                out_data_reg <= in0_data_reg + in1_data_reg;
            end else if (out_valid_reg && out_ready) begin
                out_valid_reg <= 1'b0;
            end
            // clear captured valid after PASS
            if (next_state != state && state == PASS) begin
                in0_valid_reg <= 1'b0;
                in1_valid_reg <= 1'b0;
            end
        end
    end

    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (in0_valid && in0_ready && in1_valid && in1_ready) begin
                    next_state = PASS;
                end else if ((in0_valid && in0_ready) || (in1_valid && in1_ready)) begin
                    next_state = WAIT_BOTH;
                end
            end
            WAIT_BOTH: begin
                if (in0_valid_reg && in1_valid_reg) begin
                    next_state = PASS;
                end
            end
            PASS: begin
                if (out_ready) begin
                    next_state = IDLE;
                end
            end
        endcase
    end

endmodule

module stream_stage #(
    parameter DATA_WIDTH = 16
) (
    input  wire                clk,
    input  wire                rst_n,
    input  wire                in_valid,
    input  wire [DATA_WIDTH-1:0] in_data,
    output wire                in_ready,
    output wire                out_valid,
    output wire [DATA_WIDTH-1:0] out_data,
    input  wire                out_ready
);

    reg valid_reg;
    reg [DATA_WIDTH-1:0] data_reg;

    assign in_ready = !valid_reg || (valid_reg && out_ready);
    assign out_valid = valid_reg;
    assign out_data = data_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            valid_reg <= 1'b0;
        end else begin
            if (!valid_reg) begin
                if (in_valid) begin
                    valid_reg <= 1'b1;
                    data_reg <= in_data;
                end
            end else begin
                if (out_ready) begin
                    if (in_valid) begin
                        data_reg <= in_data;
                    end else begin
                        valid_reg <= 1'b0;
                    end
                end
            end
        end
    end

endmodule

module tb_top;

    reg clk;
    reg rst_n;
    reg [7:0] in0_data, in1_data;
    reg in0_valid, in1_valid;
    wire in0_ready, in1_ready;
    wire out_valid;
    wire [15:0] out_data;
    reg out_ready;

    top dut (
        .clk(clk),
        .rst_n(rst_n),
        .in0_valid(in0_valid),
        .in0_data(in0_data),
        .in0_ready(in0_ready),
        .in1_valid(in1_valid),
        .in1_data(in1_data),
        .in1_ready(in1_ready),
        .out_valid(out_valid),
        .out_data(out_data),
        .out_ready(out_ready)
    );

    initial clk = 0;
    always #5 clk = ~clk;

    integer test_fail = 0;
    integer cycle;
    reg [15:0] expected_accum = 0;
    reg [7:0] test_data0 [0:1];
    reg [7:0] test_data1 [0:1];

    initial begin
        // Initialize
        rst_n = 0;
        in0_valid = 0;
        in1_valid = 0;
        out_ready = 0;
        in0_data = 0;
        in1_data = 0;
        #20;
        rst_n = 1;
        #10;

        // Test data
        test_data0[0] = 8'd10;
        test_data1[0] = 8'd5;
        test_data0[1] = 8'd20;
        test_data1[1] = 8'd30;

        // Send first pair
        @(posedge clk);
        in0_valid = 1; in0_data = test_data0[0];
        in1_valid = 1; in1_data = test_data1[0];
        out_ready = 1;
        @(posedge clk);
        // Wait for handshake
        while (!in0_ready || !in1_ready) @(posedge clk);
        in0_valid = 0; in1_valid = 0;
        // Wait for output
        while (!out_valid) @(posedge clk);
        expected_accum = test_data0[0] + test_data1[0];
        if (out_data !== expected_accum) begin
            $display("TEST_FAIL: Expected %0d, got %0d", expected_accum, out_data);
            test_fail = 1;
        end
        @(posedge clk);
        // Send second pair
        in0_valid = 1; in0_data = test_data0[1];
        in1_valid = 1; in1_data = test_data1[1];
        @(posedge clk);
        while (!in0_ready || !in1_ready) @(posedge clk);
        in0_valid = 0; in1_valid = 0;
        while (!out_valid) @(posedge clk);
        expected_accum = (test_data0[0] + test_data1[0]) + (test_data0[1] + test_data1[1]);
        if (out_data !== expected_accum) begin
            $display("TEST_FAIL: Expected %0d, got %0d", expected_accum, out_data);
            test_fail = 1;
        end
        @(posedge clk);

        if (test_fail) begin
            $display("TEST_FAIL");
        end else begin
            $display("TEST_PASS");
        end
        #100 $finish;
    end

endmodule

