module accumulator_core #(parameter WIDTH=8) (
    input clk, rst_n,
    input [WIDTH-1:0] s_tdata,
    input s_tvalid,
    output s_tready,
    output [WIDTH-1:0] m_tdata,
    output m_tvalid,
    input m_tready
);
reg [WIDTH-1:0] accum_val;
assign s_tready = 1'b1;
assign m_tdata = accum_val;
assign m_tvalid = 1'b1;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        accum_val <= 0;
    end else if (s_tvalid) begin
        accum_val <= accum_val + s_tdata;
    end
end
endmodule

module skid_buffer #(parameter WIDTH=8) (
    input clk, rst_n,
    input [WIDTH-1:0] s_tdata,
    input s_tvalid,
    output s_tready,
    output [WIDTH-1:0] m_tdata,
    output m_tvalid,
    input m_tready
);
localparam DEPTH = 4;
reg [WIDTH-1:0] mem [0:DEPTH-1];
reg [1:0] wr_ptr, rd_ptr;
reg [2:0] count;

assign s_tready = (count < DEPTH);
assign m_tvalid = (count > 0);
assign m_tdata = mem[rd_ptr];

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        count <= 0;
    end else begin
        if (s_tvalid && s_tready && m_tready && m_tvalid) begin
            // both write and read
            mem[wr_ptr] <= s_tdata;
            wr_ptr <= wr_ptr + 1;
            rd_ptr <= rd_ptr + 1;
            // count unchanged
        end else if (s_tvalid && s_tready) begin
            // write only
            mem[wr_ptr] <= s_tdata;
            wr_ptr <= wr_ptr + 1;
            count <= count + 1;
        end else if (m_tready && m_tvalid) begin
            // read only
            rd_ptr <= rd_ptr + 1;
            count <= count - 1;
        end
    end
end
endmodule

module stream_join #(parameter WIDTH=8) (
    input clk, rst_n,
    input [WIDTH-1:0] s0_tdata,
    input s0_tvalid,
    output s0_tready,
    input [WIDTH-1:0] s1_tdata,
    input s1_tvalid,
    output s1_tready,
    output [WIDTH-1:0] m_tdata,
    output m_tvalid,
    input m_tready
);
wire both_valid = s0_tvalid && s1_tvalid;
assign s0_tready = m_tready && both_valid;
assign s1_tready = m_tready && both_valid;
assign m_tvalid = both_valid;
assign m_tdata = s0_tdata + s1_tdata;
endmodule

module stream_stage #(parameter WIDTH=8) (
    input clk, rst_n,
    input [WIDTH-1:0] s_tdata,
    input s_tvalid,
    output s_tready,
    output reg [WIDTH-1:0] m_tdata,
    output reg m_tvalid,
    input m_tready
);
assign s_tready = !m_tvalid | (m_tready & m_tvalid);
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        m_tvalid <= 1'b0;
    end else begin
        if (s_tvalid & s_tready) begin
            m_tdata <= s_tdata;
            m_tvalid <= 1'b1;
        end else if (m_tready & m_tvalid) begin
            m_tvalid <= 1'b0;
        end
    end
end
endmodule

module top #(parameter WIDTH=8) (
    input clk, rst_n,
    input [WIDTH-1:0] s_axis0_tdata,
    input s_axis0_tvalid,
    output s_axis0_tready,
    input [WIDTH-1:0] s_axis1_tdata,
    input s_axis1_tvalid,
    output s_axis1_tready,
    output [WIDTH-1:0] m_axis_tdata,
    output m_axis_tvalid,
    input m_axis_tready
);
wire [WIDTH-1:0] in0_to_join, in1_to_join;
wire in0_to_join_valid, in1_to_join_valid;
wire in0_to_join_ready, in1_to_join_ready;
wire [WIDTH-1:0] join_to_acc;
wire join_to_acc_valid, join_to_acc_ready;
wire [WIDTH-1:0] acc_to_out;
wire acc_to_out_valid, acc_to_out_ready;

skid_buffer #(.WIDTH(WIDTH)) in0_buffer (
    .clk(clk), .rst_n(rst_n),
    .s_tdata(s_axis0_tdata), .s_tvalid(s_axis0_tvalid), .s_tready(s_axis0_tready),
    .m_tdata(in0_to_join), .m_tvalid(in0_to_join_valid), .m_tready(in0_to_join_ready)
);
skid_buffer #(.WIDTH(WIDTH)) in1_buffer (
    .clk(clk), .rst_n(rst_n),
    .s_tdata(s_axis1_tdata), .s_tvalid(s_axis1_tvalid), .s_tready(s_axis1_tready),
    .m_tdata(in1_to_join), .m_tvalid(in1_to_join_valid), .m_tready(in1_to_join_ready)
);
stream_join #(.WIDTH(WIDTH)) join_core (
    .clk(clk), .rst_n(rst_n),
    .s0_tdata(in0_to_join), .s0_tvalid(in0_to_join_valid), .s0_tready(in0_to_join_ready),
    .s1_tdata(in1_to_join), .s1_tvalid(in1_to_join_valid), .s1_tready(in1_to_join_ready),
    .m_tdata(join_to_acc), .m_tvalid(join_to_acc_valid), .m_tready(join_to_acc_ready)
);
accumulator_core #(.WIDTH(WIDTH)) accumulator (
    .clk(clk), .rst_n(rst_n),
    .s_tdata(join_to_acc), .s_tvalid(join_to_acc_valid), .s_tready(join_to_acc_ready),
    .m_tdata(acc_to_out), .m_tvalid(acc_to_out_valid), .m_tready(acc_to_out_ready)
);
stream_stage #(.WIDTH(WIDTH)) out_stage (
    .clk(clk), .rst_n(rst_n),
    .s_tdata(acc_to_out), .s_tvalid(acc_to_out_valid), .s_tready(acc_to_out_ready),
    .m_tdata(m_axis_tdata), .m_tvalid(m_axis_tvalid), .m_tready(m_axis_tready)
);
endmodule

`timescale 1ns/1ps
module tb_top;
reg clk, rst_n;
reg [7:0] s_axis0_tdata, s_axis1_tdata;
reg s_axis0_tvalid, s_axis1_tvalid;
wire s_axis0_tready, s_axis1_tready;
wire [7:0] m_axis_tdata;
wire m_axis_tvalid;
reg m_axis_tready;

top #(.WIDTH(8)) dut (.*);

initial clk = 0;
always #5 clk = ~clk;

integer errors;

task wait_for_output;
input [7:0] expected;
output reg [7:0] data;
integer wait_cnt;
begin
    wait_cnt = 0;
    while (wait_cnt < 20) begin
        @(posedge clk);
        if (m_axis_tvalid && m_axis_tready) begin
            data = m_axis_tdata;
            if (data !== expected) begin
                $display("TEST_FAIL: Expected %0d, got %0d at time %0t", expected, data, $time);
                errors = errors + 1;
            end
            return;
        end
        wait_cnt = wait_cnt + 1;
    end
    $display("TEST_FAIL: Timeout at time %0t", $time);
    errors = errors + 1;
end
endtask

initial begin
    errors = 0;
    rst_n = 0;
    s_axis0_tvalid = 0;
    s_axis1_tvalid = 0;
    m_axis_tready = 0;
    @(posedge clk);
    #1 rst_n = 1;
    @(posedge clk);
    // First pair: 1+2=3, accumulator: 3
    s_axis0_tdata = 1; s_axis0_tvalid = 1;
    s_axis1_tdata = 2; s_axis1_tvalid = 1;
    m_axis_tready = 1;
    @(posedge clk);
    s_axis0_tvalid = 0; s_axis1_tvalid = 0;
    wait_for_output(3, ); // ignore output data
    // Second pair: 3+4=7, accumulator: 3+7=10
    s_axis0_tdata = 3; s_axis0_tvalid = 1;
    s_axis1_tdata = 4; s_axis1_tvalid = 1;
    @(posedge clk);
    s_axis0_tvalid = 0; s_axis1_tvalid = 0;
    wait_for_output(10, );
    // Third pair: 5+6=11, accumulator: 10+11=21
    s_axis0_tdata = 5; s_axis0_tvalid = 1;
    s_axis1_tdata = 6; s_axis1_tvalid = 1;
    @(posedge clk);
    s_axis0_tvalid = 0; s_axis1_tvalid = 0;
    wait_for_output(21, );

    if (errors == 0) begin
        $display("TEST_PASS");
    end else begin
        $display("TEST_FAIL: %0d errors", errors);
    end
    $finish;
end
endmodule

