module accumulator_core #(
    parameter WIDTH = 8
) (
    input  wire clk,
    input  wire rst_n,
    input  wire [WIDTH-1:0] in_data,
    input  wire in_valid,
    output wire in_ready,
    input  wire clear,
    output wire [WIDTH-1:0] out_data,
    output wire out_valid,
    input  wire out_ready
);

    reg [WIDTH-1:0] acc_reg;

    assign out_data = acc_reg;
    assign out_valid = 1'b1;
    assign in_ready = out_ready;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            acc_reg <= 0;
        end else if (clear) begin
            acc_reg <= 0;
        end else if (in_valid & in_ready) begin
            acc_reg <= acc_reg + in_data;
        end
    end

endmodule

module skid_buffer #(
    parameter WIDTH = 8,
    parameter DEPTH = 2
) (
    input  wire clk,
    input  wire rst_n,
    input  wire [WIDTH-1:0] in_data,
    input  wire in_valid,
    output wire in_ready,
    output wire [WIDTH-1:0] out_data,
    output wire out_valid,
    input  wire out_ready
);

    reg [WIDTH-1:0] buf [0:DEPTH-1];
    reg [$clog2(DEPTH+1)-1:0] count;

    wire push = in_valid & in_ready;
    wire pop = out_valid & out_ready;

    assign in_ready = (count < DEPTH);
    assign out_valid = (count > 0);
    assign out_data = buf[0];

    integer i;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count <= 0;
            for (i = 0; i < DEPTH; i = i + 1) buf[i] <= 0;
        end else begin
            if (push && !pop) begin
                buf[count] <= in_data;
                count <= count + 1;
            end else if (!push && pop) begin
                for (i = 0; i < DEPTH-1; i = i + 1) buf[i] <= buf[i+1];
                buf[DEPTH-1] <= 0;
                count <= count - 1;
            end else if (push && pop) begin
                for (i = 0; i < DEPTH-1; i = i + 1) buf[i] <= buf[i+1];
                buf[DEPTH-1] <= in_data;
                count <= count;
            end
        end
    end

endmodule

module stream_join #(
    parameter WIDTH = 8
) (
    input  wire clk,
    input  wire rst_n,
    input  wire [WIDTH-1:0] in0_data,
    input  wire in0_valid,
    output wire in0_ready,
    input  wire [WIDTH-1:0] in1_data,
    input  wire in1_valid,
    output wire in1_ready,
    output wire [WIDTH-1:0] out_data,
    output wire out_valid,
    input  wire out_ready
);

    assign in0_ready = in1_valid & out_ready;
    assign in1_ready = in0_valid & out_ready;
    assign out_valid = in0_valid & in1_valid;
    assign out_data = in0_data + in1_data;

endmodule

module stream_stage #(
    parameter WIDTH = 8
) (
    input  wire clk,
    input  wire rst_n,
    input  wire [WIDTH-1:0] in_data,
    input  wire in_valid,
    output wire in_ready,
    output wire [WIDTH-1:0] out_data,
    output wire out_valid,
    input  wire out_ready
);

    reg [WIDTH-1:0] out_data_reg;
    reg valid;

    assign in_ready = !valid || out_ready;
    assign out_data = out_data_reg;
    assign out_valid = valid;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            valid <= 1'b0;
            out_data_reg <= 0;
        end else if (in_valid & in_ready) begin
            out_data_reg <= in_data;
            valid <= 1'b1;
        end else if (out_ready & valid) begin
            valid <= 1'b0;
        end
    end

endmodule

