module accumulator_core #(parameter W = 8) (
  input clk, reset_n,
  input valid_in,
  input [W-1:0] data_in,
  output ready_out,
  output valid_out,
  output [W-1:0] data_out,
  input ready_in
);

reg [W-1:0] acc_reg;
reg acc_valid;

assign ready_out = !acc_valid || (acc_valid && ready_in);
assign valid_out = acc_valid;
assign data_out = acc_reg;

always @(posedge clk or negedge reset_n) begin
  if (!reset_n) begin
    acc_reg <= 0;
    acc_valid <= 0;
  end else begin
    if (valid_in && ready_out) begin
      acc_reg <= acc_reg + data_in;
      acc_valid <= 1;
    end else if (ready_in && acc_valid) begin
      acc_valid <= 0;
    end
  end
end

endmodule

module skid_buffer #(parameter W = 8) (
  input clk, reset_n,
  input valid_in,
  input [W-1:0] data_in,
  output ready_out,
  output valid_out,
  output [W-1:0] data_out,
  input ready_in
);

reg [W-1:0] data_store;
reg store_valid;

assign ready_out = !store_valid || (store_valid && ready_in);
assign valid_out = store_valid;
assign data_out = data_store;

always @(posedge clk or negedge reset_n) begin
  if (!reset_n) begin
    store_valid <= 0;
    data_store <= 0;
  end else begin
    if (valid_in && ready_out) begin
      data_store <= data_in;
      store_valid <= 1;
    end else if (ready_in && store_valid) begin
      store_valid <= 0;
    end
  end
end

endmodule

module stream_join #(parameter W = 8) (
  input clk, reset_n,
  input valid0,
  input [W-1:0] data0,
  output ready0,
  input valid1,
  input [W-1:0] data1,
  output ready1,
  output valid_out,
  output [W-1:0] data_out,
  input ready_in
);

parameter [1:0] IDLE = 2'b00, WAIT0 = 2'b01, WAIT1 = 2'b10, JOIN = 2'b11;

reg [1:0] state;
reg [W-1:0] buf_data0, buf_data1;

wire [W-1:0] sum = buf_data0 + buf_data1;

always @(posedge clk or negedge reset_n) begin
  if (!reset_n) begin
    state <= IDLE;
    buf_data0 <= 0;
    buf_data1 <= 0;
  end else begin
    case (state)
      IDLE: begin
        if (valid0 && valid1 && ready_in) begin
          buf_data0 <= data0;
          buf_data1 <= data1;
          state <= JOIN;
        end else if (valid0) begin
          buf_data0 <= data0;
          state <= WAIT1;
        end else if (valid1) begin
          buf_data1 <= data1;
          state <= WAIT0;
        end
      end
      WAIT0: begin
        if (valid0 && ready_in) begin
          buf_data0 <= data0;
          state <= JOIN;
        end
      end
      WAIT1: begin
        if (valid1 && ready_in) begin
          buf_data1 <= data1;
          state <= JOIN;
        end
      end
      JOIN: begin
        if (ready_in) begin
          state <= IDLE;
        end
      end
    endcase
  end
end

assign ready0 = (state == IDLE) || (state == WAIT0);
assign ready1 = (state == IDLE) || (state == WAIT1);
assign valid_out = (state == JOIN);
assign data_out = sum;

endmodule

module stream_stage #(parameter W = 8) (
  input clk, reset_n,
  input valid_in,
  input [W-1:0] data_in,
  output ready_out,
  output valid_out,
  output [W-1:0] data_out,
  input ready_in
);

reg [W-1:0] stage_reg;
reg stage_valid;

assign ready_out = !stage_valid || (stage_valid && ready_in);
assign valid_out = stage_valid;
assign data_out = stage_reg;

always @(posedge clk or negedge reset_n) begin
  if (!reset_n) begin
    stage_reg <= 0;
    stage_valid <= 0;
  end else begin
    if (valid_in && ready_out) begin
      stage_reg <= data_in;
      stage_valid <= 1;
    end else if (ready_in && stage_valid) begin
      stage_valid <= 0;
    end
  end
end

endmodule

module top (
  input clk, reset_n,
  input in0_valid, input [7:0] in0_data, output in0_ready,
  input in1_valid, input [7:0] in1_data, output in1_ready,
  output out_valid, output [7:0] out_data, input out_ready
);

wire [7:0] buf0_data, buf1_data;
wire buf0_valid, buf1_valid;
wire buf0_ready_in, buf1_ready_in;

skid_buffer #(.W(8)) in0_buffer (
  .clk(clk), .reset_n(reset_n),
  .valid_in(in0_valid), .data_in(in0_data), .ready_out(in0_ready),
  .valid_out(buf0_valid), .data_out(buf0_data),
  .ready_in(buf0_ready_in)
);

skid_buffer #(.W(8)) in1_buffer (
  .clk(clk), .reset_n(reset_n),
  .valid_in(in1_valid), .data_in(in1_data), .ready_out(in1_ready),
  .valid_out(buf1_valid), .data_out(buf1_data),
  .ready_in(buf1_ready_in)
);

wire [7:0] join_data;
wire join_valid;
wire join_ready_in;
wire join_ready0, join_ready1;

stream_join #(.W(8)) join_core (
  .clk(clk), .reset_n(reset_n),
  .valid0(buf0_valid), .data0(buf0_data), .ready0(join_ready0),
  .valid1(buf1_valid), .data1(buf1_data), .ready1(join_ready1),
  .valid_out(join_valid), .data_out(join_data),
  .ready_in(join_ready_in)
);

assign buf0_ready_in = join_ready0;
assign buf1_ready_in = join_ready1;

wire [7:0] acc_data;
wire acc_valid;
wire acc_ready_in;

accumulator_core #(.W(8)) accumulator (
  .clk(clk), .reset_n(reset_n),
  .valid_in(join_valid), .data_in(join_data), .ready_out(join_ready_in),
  .valid_out(acc_valid), .data_out(acc_data),
  .ready_in(acc_ready_in)
);

wire [7:0] out_data_in;
wire out_valid_in;
wire out_ready_out;

stream_stage #(.W(8)) out_stage (
  .clk(clk), .reset_n(reset_n),
  .valid_in(acc_valid), .data_in(acc_data), .ready_out(acc_ready_in),
  .valid_out(out_valid_in), .data_out(out_data_in),
  .ready_in(out_ready)
);

assign out_valid = out_valid_in;
assign out_data = out_data_in;

endmodule

module tb_top;

reg clk, reset_n;
reg in0_valid, in1_valid;
reg [7:0] in0_data, in1_data;
wire in0_ready, in1_ready;
wire out_valid;
wire [7:0] out_data;
reg out_ready;

top dut (
  .clk(clk), .reset_n(reset_n),
  .in0_valid(in0_valid), .in0_data(in0_data), .in0_ready(in0_ready),
  .in1_valid(in1_valid), .in1_data(in1_data), .in1_ready(in1_ready),
  .out_valid(out_valid), .out_data(out_data), .out_ready(out_ready)
);

always #5 clk = ~clk;

initial begin
  $dumpfile("tb_top.vcd");
  $dumpvars(0, tb_top);
  clk = 0;
  reset_n = 0;
  in0_valid = 0; in0_data = 0;
  in1_valid = 0; in1_data = 0;
  out_ready = 1;
  #20 reset_n = 1;
  #10;
  // First pair
  in0_data = 8'd1; in0_valid = 1;
  in1_data = 8'd2; in1_valid = 1;
  #10;
  in0_valid = 0; in1_valid = 0;
  #30;
  // Second pair
  in0_data = 8'd3; in0_valid = 1;
  in1_data = 8'd4; in1_valid = 1;
  #10;
  in0_valid = 0; in1_valid = 0;
  #50;
  // Check output
  if (out_data == 8'd7) begin
    $display("TEST_PASS");
  end else begin
    $display("TEST_FAIL");
  end
  $finish;
end

endmodule

