`timescale 1ns / 1ps

module accumulator_core #(parameter WIDTH = 8) (
    input  wire clk,
    input  wire rst_n,
    input  wire [WIDTH*2-1:0] data_in,
    input  wire valid_in,
    output wire ready_out,
    output wire [WIDTH-1:0] data_out,
    output wire valid_out,
    input  wire ready_in
);

    reg [WIDTH-1:0] acc_reg;
    reg valid_reg;

    // ready_out: always ready to accept if we are not holding a valid output that hasn't been taken
    assign ready_out = !valid_reg || ready_in;
    assign data_out = acc_reg;
    assign valid_out = valid_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            acc_reg <= {WIDTH{1'b0}};
            valid_reg <= 1'b0;
        end else begin
            if (valid_reg) begin
                // We have a valid output: if ready_in is high, we clear valid_reg
                if (ready_in) begin
                    valid_reg <= 1'b0;
                end
            end
            if (valid_in && ready_out) begin
                // Input accepted: accumulate
                // Add the two halves: data_in[WIDTH-1:0] and data_in[2*WIDTH-1:WIDTH]
                acc_reg <= acc_reg + data_in[WIDTH-1:0] + data_in[2*WIDTH-1:WIDTH];
                valid_reg <= 1'b1;
            end
        end
    end

endmodule

`timescale 1ns / 1ps

module skid_buffer #(parameter WIDTH = 8) (
    input  wire clk,
    input  wire rst_n,
    input  wire [WIDTH-1:0] data_in,
    input  wire valid_in,
    output wire ready_out,
    output wire [WIDTH-1:0] data_out,
    output wire valid_out,
    input  wire ready_in
);

    reg [WIDTH-1:0] buffer_reg;
    reg full;

    // ready_out: accept input if not full
    assign ready_out = !full;
    // valid_out: we have data if full
    assign valid_out = full;
    assign data_out = buffer_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            full <= 1'b0;
            buffer_reg <= {WIDTH{1'b0}};
        end else begin
            // Update full and buffer
            if (!full) begin
                // Buffer empty: can load if valid_in
                if (valid_in) begin
                    buffer_reg <= data_in;
                    full <= 1'b1;
                end
            end else begin
                // Buffer full: if downstream ready, we output and possibly load new data
                if (ready_in) begin
                    if (valid_in) begin
                        // Simultaneous output and input: update buffer
                        buffer_reg <= data_in;
                    end else begin
                        // No new input: buffer empties
                        full <= 1'b0;
                    end
                end
                // else stay full
            end
        end
    end

endmodule

`timescale 1ns / 1ps

module stream_join #(parameter WIDTH = 8) (
    input  wire clk,
    input  wire rst_n,
    input  wire [WIDTH-1:0] in0_data,
    input  wire in0_valid,
    output wire in0_ready,
    input  wire [WIDTH-1:0] in1_data,
    input  wire in1_valid,
    output wire in1_ready,
    output wire [WIDTH*2-1:0] out_data,
    output wire out_valid,
    input  wire out_ready
);

    // State machine for joining
    localparam [1:0] IDLE = 2'd0,
                     OUTPUT = 2'd1;
    // Note: WAIT_IN0 and WAIT_IN1 not used; we wait for both simultaneously

    reg [1:0] state;
    reg [WIDTH-1:0] reg0, reg1;
    reg join_valid_internal;

    assign in0_ready = (state == IDLE) ? ~join_valid_internal : 1'b0;
    assign in1_ready = (state == IDLE) ? ~join_valid_internal : 1'b0;
    assign out_data = {reg1, reg0}; // concatenation: in1 is high byte, in0 low byte
    assign out_valid = join_valid_internal;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            reg0 <= {WIDTH{1'b0}};
            reg1 <= {WIDTH{1'b0}};
            join_valid_internal <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (in0_valid && in1_valid) begin
                        reg0 <= in0_data;
                        reg1 <= in1_data;
                        join_valid_internal <= 1'b1;
                        state <= OUTPUT;
                    end
                end
                OUTPUT: begin
                    if (out_ready) begin
                        join_valid_internal <= 1'b0;
                        state <= IDLE;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end

endmodule

`timescale 1ns / 1ps

module stream_stage #(parameter WIDTH = 8) (
    input  wire clk,
    input  wire rst_n,
    input  wire [WIDTH-1:0] data_in,
    input  wire valid_in,
    output wire ready_out,
    output wire [WIDTH-1:0] data_out,
    output wire valid_out,
    input  wire ready_in
);

    reg [WIDTH-1:0] pipeline_reg;
    reg valid_reg;

    assign ready_out = !valid_reg || ready_in;
    assign data_out = pipeline_reg;
    assign valid_out = valid_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pipeline_reg <= {WIDTH{1'b0}};
            valid_reg <= 1'b0;
        end else begin
            if (valid_reg) begin
                if (ready_in) begin
                    valid_reg <= 1'b0;
                end
            end
            if (valid_in && ready_out) begin
                pipeline_reg <= data_in;
                valid_reg <= 1'b1;
            end
        end
    end

endmodule

`timescale 1ns / 1ps

module top #(parameter WIDTH = 8) (
    input  wire clk,
    input  wire rst_n,
    input  wire [WIDTH-1:0] in0_data,
    input  wire in0_valid,
    output wire in0_ready,
    input  wire [WIDTH-1:0] in1_data,
    input  wire in1_valid,
    output wire in1_ready,
    output wire [WIDTH-1:0] out_data,
    output wire out_valid,
    input  wire out_ready
);

    // Internal wires
    wire [WIDTH-1:0] buf0_data;
    wire buf0_valid;
    wire buf0_ready;
    wire [WIDTH-1:0] buf1_data;
    wire buf1_valid;
    wire buf1_ready;
    wire [WIDTH*2-1:0] join_data;
    wire join_valid;
    wire join_ready;
    wire [WIDTH-1:0] acc_data;
    wire acc_valid;
    wire acc_ready;
    wire [WIDTH-1:0] staged_data;
    wire staged_valid;
    wire staged_ready;

    // Control signals for join_count
    reg [7:0] join_count;
    wire inc_count;

    // Instantiations
    skid_buffer #(.WIDTH(WIDTH)) in0_buffer (
        .clk(clk),
        .rst_n(rst_n),
        .data_in(in0_data),
        .valid_in(in0_valid),
        .ready_out(in0_ready),
        .data_out(buf0_data),
        .valid_out(buf0_valid),
        .ready_in(buf0_ready)
    );

    skid_buffer #(.WIDTH(WIDTH)) in1_buffer (
        .clk(clk),
        .rst_n(rst_n),
        .data_in(in1_data),
        .valid_in(in1_valid),
        .ready_out(in1_ready),
        .data_out(buf1_data),
        .valid_out(buf1_valid),
        .ready_in(buf1_ready)
    );

    stream_join #(.WIDTH(WIDTH)) join_core (
        .clk(clk),
        .rst_n(rst_n),
        .in0_data(buf0_data),
        .in0_valid(buf0_valid),
        .in0_ready(buf0_ready),
        .in1_data(buf1_data),
        .in1_valid(buf1_valid),
        .in1_ready(buf1_ready),
        .out_data(join_data),
        .out_valid(join_valid),
        .out_ready(join_ready)
    );

    accumulator_core #(.WIDTH(WIDTH)) accumulator (
        .clk(clk),
        .rst_n(rst_n),
        .data_in(join_data),
        .valid_in(join_valid),
        .ready_out(join_ready),
        .data_out(acc_data),
        .valid_out(acc_valid),
        .ready_in(acc_ready)
    );

    stream_stage #(.WIDTH(WIDTH)) out_stage (
        .clk(clk),
        .rst_n(rst_n),
        .data_in(acc_data),
        .valid_in(acc_valid),
        .ready_out(acc_ready),
        .data_out(staged_data),
        .valid_out(staged_valid),
        .ready_in(out_ready)
    );

    // Outputs
    assign out_data = staged_data;
    assign out_valid = staged_valid;

    // join_count increment condition (from accumulator update)
    assign inc_count = acc_valid & acc_ready;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            join_count <= 8'd0;
        end else if (inc_count) begin
            join_count <= join_count + 1;
        end
    end

endmodule

