);

wire sclk_int;
wire start_sync;
reg [1:0] start_sync_reg;
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) start_sync_reg <= 2'b00;
    else start_sync_reg <= {start_sync_reg[0], start};
end
assign start_sync = start_sync_reg[1];

clock_divider #(.DIV(100)) u_div (
