module skid_buffer #(parameter WIDTH=8) (
    input clk,
    input rst_n,
    input [WIDTH-1:0] in_data,
    input in_valid,
    output reg in_ready,
    output reg out_valid,
    output reg [WIDTH-1:0] out_data,
    input out_ready
);
    reg [WIDTH-1:0] buf_data;
    reg buf_valid;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            out_valid <= 0;
            buf_valid <= 0;
            out_data <= 0;
            buf_data <= 0;
        end else begin
            if (out_ready && out_valid) begin
                out_valid <= 0;
            end
            if (buf_valid && !out_valid) begin
                out_valid <= 1;
                out_data <= buf_data;
                buf_valid <= 0;
            end
            if (in_valid && in_ready) begin
                if (!out_valid) begin
                    out_valid <= 1;
                    out_data <= in_data;
                end else begin
                    if (!buf_valid) begin
                        buf_valid <= 1;
                        buf_data <= in_data;
                    end
                end
            end
        end
    end
    assign in_ready = !buf_valid && (!out_valid || out_ready);
endmodule

module stream_fork #(parameter WIDTH=8) (
    input clk,
    input rst_n,
    input [WIDTH-1:0] in_data,
    input in_valid,
    output in_ready,
    output [WIDTH-1:0] out0_data,
    output out0_valid,
    input out0_ready,
    output [WIDTH-1:0] out1_data,
    output out1_valid,
    input out1_ready
);
    assign in_ready = out0_ready & out1_ready;
    assign out0_valid = in_valid;
    assign out0_data = in_data;
    assign out1_valid = in_valid;
    assign out1_data = in_data;
endmodule

module stream_stage #(parameter WIDTH=8) (
    input clk,
    input rst_n,
    input [WIDTH-1:0] in_data,
    input in_valid,
    output in_ready,
    output [WIDTH-1:0] out_data,
    output out_valid,
    input out_ready
);
    reg [WIDTH-1:0] data_reg;
    reg valid_reg;
    assign in_ready = !valid_reg || out_ready;
    assign out_valid = valid_reg;
    assign out_data = data_reg;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            valid_reg <= 0;
            data_reg <= 0;
        end else begin
            if (out_ready && valid_reg) begin
                valid_reg <= 0;
            end
            if (in_valid && in_ready) begin
                data_reg <= in_data;
                valid_reg <= 1;
            end
        end
    end
endmodule

