module accumulator_core #(parameter W=8) (
    input clk, rst_n,
    input sample_valid, input [W-1:0] sample,
    output reg sample_ready,
    output reg sum_valid, output reg [W-1:0] sum,
    input sum_ready
);
    reg [W-1:0] acc;
    reg state;
    localparam IDLE = 0, HOLD = 1;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            acc <= 0;
            sum_valid <= 0;
            sample_ready <= 1;
            state <= IDLE;
        end else begin
            case(state)
                IDLE: begin
                    sample_ready <= 1;
                    if (sample_valid) begin
                        acc <= acc + sample;
                        sum <= acc + sample;
                        sum_valid <= 1;
                        state <= HOLD;
                        sample_ready <= 0;
                    end else begin
                        sum_valid <= 0;
                    end
                end
                HOLD: begin
                    sample_ready <= 0;
                    if (sum_ready) begin
                        state <= IDLE;
                        sum_valid <= 0;
                    end
                end
            endcase
        end
    end
endmodule

module skid_buffer #(parameter W=8) (
    input clk, rst_n,
    input in_valid, input [W-1:0] in_data,
    output reg in_ready,
    output reg out_valid, output reg [W-1:0] out_data,
    input out_ready
);
    reg [W-1:0] buf_data;
    reg buf_valid;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            out_valid <= 0;
            buf_valid <= 0;
            in_ready <= 1;
        end else begin
            if (out_valid && out_ready) begin
                if (buf_valid) begin
                    out_data <= buf_data;
                    buf_valid <= 0;
                    in_ready <= 1;
                end else begin
                    out_valid <= 0;
                    in_ready <= 1;
                end
            end else if (!out_valid && in_valid) begin
                out_valid <= 1;
                out_data <= in_data;
                in_ready <= 1;
            end else if (out_valid && !out_ready && in_valid) begin
                buf_valid <= 1;
                buf_data <= in_data;
                in_ready <= 0;
            end
        end
    end
endmodule

module stream_join #(parameter W=8) (
    input clk, rst_n,
    input in0_valid, input [W-1:0] in0_data,
    output reg in0_ready,
    input in1_valid, input [W-1:0] in1_data,
    output reg in1_ready,
    output reg out_valid, output reg [W-1:0] out_data,
    input out_ready
);
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            out_valid <= 0;
            in0_ready <= 1;
            in1_ready <= 1;
        end else begin
            if (!out_valid || out_ready) begin
                if (in0_valid && in1_valid) begin
                    out_valid <= 1;
                    out_data <= in0_data + in1_data;
                    in0_ready <= 1;
                    in1_ready <= 1;
                end else begin
                    out_valid <= 0;
                    in0_ready <= 1;
                    in1_ready <= 1;
                end
            end else begin
                in0_ready <= 0;
                in1_ready <= 0;
            end
        end
    end
endmodule

module stream_stage #(parameter W=8) (
    input clk, rst_n,
    input in_valid, input [W-1:0] in_data,
    output reg in_ready,
    output reg out_valid, output reg [W-1:0] out_data,
    input out_ready
);
    reg [W-1:0] buf;
    reg buf_valid;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            buf_valid <= 0;
            out_valid <= 0;
            in_ready <= 1;
        end else begin
            if (out_valid && out_ready) begin
                out_valid <= buf_valid;
                out_data <= buf;
                buf_valid <= 0;
                in_ready <= 1;
            end else if (!out_valid) begin
                if (in_valid) begin
                    out_valid <= 1;
                    out_data <= in_data;
                    in_ready <= 1;
                end else begin
                    out_valid <= 0;
                    in_ready <= 1;
                end
            end else if (!out_ready) begin
                if (in_valid && !buf_valid) begin
                    buf_valid <= 1;
                    buf <= in_data;
                    in_ready <= 0;
                end else begin
                    in_ready <= 1;
                end
            end
        end
    end
endmodule

module top (
    input clk,
    input rst_n,
    input in0_valid,
    input [7:0] in0_data,
    output in0_ready,
    input in1_valid,
    input [7:0] in1_data,
    output in1_ready,
    output out_valid,
    output [7:0] out_data,
    input out_ready
);
    wire skid0_out_valid, skid1_out_valid;
    wire [7:0] skid0_out_data, skid1_out_data;
    wire skid0_out_ready, skid1_out_ready;
    wire join_out_valid;
    wire [7:0] join_out_data;
    wire join_out_ready;
    wire acc_sample_valid;
    wire [7:0] acc_sample;
    wire acc_sample_ready;
    wire acc_sum_valid;
    wire [7:0] acc_sum;
    wire acc_sum_ready;

    skid_buffer #(8) skid0 (
        .clk(clk), .rst_n(rst_n),
        .in_valid(in0_valid), .in_data(in0_data), .in_ready(in0_ready),
        .out_valid(skid0_out_valid), .out_data(skid0_out_data), .out_ready(skid0_out_ready)
    );
    skid_buffer #(8) skid1 (
        .clk(clk), .rst_n(rst_n),
        .in_valid(in1_valid), .in_data(in1_data), .in_ready(in1_ready),
        .out_valid(skid1_out_valid), .out_data(skid1_out_data), .out_ready(skid1_out_ready)
    );
    stream_join #(8) join_inst (
        .clk(clk), .rst_n(rst_n),
        .in0_valid(skid0_out_valid), .in0_data(skid0_out_data), .in0_ready(skid0_out_ready),
        .in1_valid(skid1_out_valid), .in1_data(skid1_out_data), .in1_ready(skid1_out_ready),
        .out_valid(join_out_valid), .out_data(join_out_data), .out_ready(join_out_ready)
    );
    accumulator_core #(8) acc_inst (
        .clk(clk), .rst_n(rst_n),
        .sample_valid(join_out_valid), .sample(join_out_data), .sample_ready(join_out_ready),
        .sum_valid(acc_sum_valid), .sum(acc_sum), .sum_ready(acc_sum_ready)
    );
    stream_stage #(8) stage_inst (
        .clk(clk), .rst_n(rst_n),
        .in_valid(acc_sum_valid), .in_data(acc_sum), .in_ready(acc_sum_ready),
        .out_valid(out_valid), .out_data(out_data), .out_ready(out_ready)
    );
endmodule

`timescale 1ns/1ns
module tb_top;
    reg clk, rst_n;
    reg [7:0] in0_data, in1_data;
    reg in0_valid, in1_valid;
    wire in0_ready, in1_ready;
    wire [7:0] out_data;
    wire out_valid;
    reg out_ready;
    integer errors;

    top uut (
        .clk(clk), .rst_n(rst_n),
        .in0_valid(in0_valid), .in0_data(in0_data), .in0_ready(in0_ready),
        .in1_valid(in1_valid), .in1_data(in1_data), .in1_ready(in1_ready),
        .out_valid(out_valid), .out_data(out_data), .out_ready(out_ready)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        rst_n = 0;
        in0_valid = 0; in1_valid = 0;
        out_ready = 1;
        errors = 0;
        #20 rst_n = 1;
        #10;

        // Test sequence
        // First pair: in0=1, in1=2 => sum=3, accumulator gets 3, output should be 3
        @(posedge clk);
        in0_valid = 1; in0_data = 8'd1;
        in1_valid = 1; in1_data = 8'd2;
        out_ready = 1;
        @(posedge clk);
        if (out_valid && out_data !== 8'd3) begin
            $display("ERROR: Expected 3, got %d", out_data);
            errors = errors + 1;
        end
        // Second pair: in0=3, in1=4 => sum=7, accumulated=3+7=10, output should be 10
        @(posedge clk);
        in0_valid = 1; in0_data = 8'd3;
        in1_valid = 1; in1_data = 8'd4;
        out_ready = 1;
        @(posedge clk);
        if (out_valid && out_data !== 8'd10) begin
            $display("ERROR: Expected 10, got %d", out_data);
            errors = errors + 1;
        end
        // Third pair: in0=5, in1=6 => sum=11, accumulated=10+11=21, output should be 21
        @(posedge clk);
        in0_valid = 1; in0_data = 8'd5;
        in1_valid = 1; in1_data = 8'd6;
        out_ready = 1;
        @(posedge clk);
        if (out_valid && out_data !== 8'd21) begin
            $display("ERROR: Expected 21, got %d", out_data);
            errors = errors + 1;
        end
        #100;
        if (errors === 0)
            $display("TEST_PASS");
        else
            $display("TEST_FAIL");
        $finish;
    end
endmodule

